import{_ as a,o as r,c as i,ai as t}from"./chunks/framework.ampVZV4B.js";const p=JSON.parse('{"title":"Agent 面试 · 场景设计题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/scenario-interview.md","filePath":"guide/agent/scenario-interview.md"}'),l={name:"guide/agent/scenario-interview.md"};function n(o,e,s,g,d,c){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="agent-面试-·-场景设计题" tabindex="-1">Agent 面试 · 场景设计题 <a class="header-anchor" href="#agent-面试-·-场景设计题" aria-label="Permalink to “Agent 面试 · 场景设计题”">​</a></h1><blockquote><p>白板/口述：「给一个需求，你怎么设计 Agent？」按固定套路答，不慌。</p></blockquote><hr><h2 id="答题骨架-每次套用" tabindex="-1">答题骨架（每次套用） <a class="header-anchor" href="#答题骨架-每次套用" aria-label="Permalink to “答题骨架（每次套用）”">​</a></h2><ol><li><strong>澄清目标</strong>：输入、输出、成功标准、谁来验收</li><li><strong>要不要 Agent</strong>：能否规则/工作流搞定？知识问题是否先 RAG？</li><li><strong>工具清单</strong>：只读 / 写入分开；每个工具一句话</li><li><strong>主循环</strong>：步数上限、结束条件</li><li><strong>状态与存储</strong>：任务状态机、幂等</li><li><strong>护栏</strong>：权限、审批、观测</li><li><strong>演进</strong>：V0 最小闭环 → 再加能力</li></ol><hr><h2 id="练习题-a-企业内部「请假助手」" tabindex="-1">练习题 A：企业内部「请假助手」 <a class="header-anchor" href="#练习题-a-企业内部「请假助手」" aria-label="Permalink to “练习题 A：企业内部「请假助手」”">​</a></h2><p><strong>题面：</strong> 员工自然语言请假，要写进 OA，并通知主管。</p><p><strong>答法要点：</strong></p><ul><li>V0 可不做全自动：抽字段（时间、类型、时长）→ 表单预填 → <strong>人点确认</strong>再提交 OA。</li><li>工具：<code>get_user</code>、<code>create_leave_draft</code>、<code>submit_leave</code>（提交需确认）、<code>notify_manager</code>。</li><li>风险：日期解析错、重复提交 → Schema + 幂等 + 确认态。</li><li>知识：「公司请假制度」用 RAG，办事用 Agent/工具。</li></ul><hr><h2 id="练习题-b-客服「查订单-催发货」" tabindex="-1">练习题 B：客服「查订单 + 催发货」 <a class="header-anchor" href="#练习题-b-客服「查订单-催发货」" aria-label="Permalink to “练习题 B：客服「查订单 + 催发货」”">​</a></h2><p><strong>题面：</strong> 用户问物流，偶发要催促仓库。</p><p><strong>答法要点：</strong></p><ul><li>查物流：只读工具，可自动。</li><li>催发货：写操作，校验身份与订单归属，必要时人工。</li><li>限流：同一订单 N 小时内催一次。</li><li>观测：催发货成功率、误催率。</li></ul><hr><h2 id="练习题-c-工业现场「产线知识问答」" tabindex="-1">练习题 C：工业现场「产线知识问答」 <a class="header-anchor" href="#练习题-c-工业现场「产线知识问答」" aria-label="Permalink to “练习题 C：工业现场「产线知识问答」”">​</a></h2><p><strong>题面：</strong> 班组长问工艺参数、故障经验。</p><p><strong>答法要点：</strong></p><ul><li>主路径是 <strong>RAG</strong>（工艺文档、维修单），不是重 Agent。</li><li>Agent 仅在需要时调：<code>search_kb</code>、<code>get_device_status</code>（实时点）。</li><li>禁止：Agent 直接下发改 PLC；写入必须走既有工单/审批。</li><li>强调：<strong>回答要带来源片段</strong>，方便追责。</li></ul><hr><h2 id="练习题-d-研发「用-ai-改一个小-bug」" tabindex="-1">练习题 D：研发「用 AI 改一个小 Bug」 <a class="header-anchor" href="#练习题-d-研发「用-ai-改一个小-bug」" aria-label="Permalink to “练习题 D：研发「用 AI 改一个小 Bug」”">​</a></h2><p><strong>题面：</strong> 你怎么用 Code Agent，又怎么保证不乱改？</p><p><strong>答法要点：</strong></p><ul><li>范围：指定文件 / 测试命令；禁止无测试直接合入。</li><li>流程：复现 → 最小改动 → 跑测试 → 出 diff 人审。</li><li>和 Cursor / Claude Code 的关系：产品是载体，工程纪律是护栏。</li><li>可挂你站上的 <a href="/my-vitepress-site/ai/dev/coding/">AI Coding</a> 实践。</li></ul><hr><h2 id="面试官爱听的收尾" tabindex="-1">面试官爱听的收尾 <a class="header-anchor" href="#面试官爱听的收尾" aria-label="Permalink to “面试官爱听的收尾”">​</a></h2><blockquote><p>「我先做可确认的最小闭环，写操作带审批和幂等，用成功率和费用看是不是该扩大自主范围。」</p></blockquote>',28)])])}const u=a(l,[["render",n]]);export{p as __pageData,u as default};
